output_text:
[
  {
    "id": "must_pick_up_entry_cart",
    "text": "Shoppers are obliged to take the available cart from the entry cart station before doing the trip.",
    "abstraction": {
      "state_properties": {
        "entry_cart_station": "at(1,5)",
        "cart_available_at_entry": "cartAt(1,5)"
      },
      "events": {
        "pickup_entry_cart": {
          "pre": {
            "and": [
              "entry_cart_station",
              "cart_available_at_entry",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entry_cart"
    }
  },
  {
    "id": "no_hand_shopping",
    "text": "Shoppers are prohibited from carrying merchandise by hand instead of using a cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_item_by_hand",
          "cartless_item_pickup"
        ]
      }
    }
  },
  {
    "id": "return_cart_after_item_pickup",
    "text": "After placing any required item into the cart, the shopper is obliged to return the cart to the return bay before leaving.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "load_item_into_cart": {
          "pre": {
            "and": [
              "hasCart",
              "PICKUP_ITEM"
            ]
          },
          "post": "hasCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "cart_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "load_item_into_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "only_park_cart_in_return_bay",
    "text": "A cart may only be put down at the designated return bay.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "not_at_cart_return_bay": {
          "not": "cart_return_bay"
        }
      },
      "events": {
        "park_cart_outside_return_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "not_at_cart_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "park_cart_outside_return_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "Shoppers are prohibited from leaving the store while still pushing or holding a cart.",
    "abstraction": {
      "state_properties": {
        "exit_cell": "at(9,5)",
        "with_cart": "hasCart"
      },
      "events": {
        "exit_store_with_cart": {
          "pre": {
            "and": [
              "exit_cell",
              "with_cart",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_store_with_cart"
    }
  },
  {
    "id": "must_park_before_leaving_return_bay",
    "text": "Once a shopper reaches the cart return bay with a cart, they are prohibited from moving away until they have parked the cart there.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "with_cart": "hasCart"
      },
      "events": {
        "move_away_from_return_bay_with_cart": {
          "pre": {
            "and": [
              "cart_return_bay",
              "with_cart",
              "MOVE"
            ]
          },
          "post": {
            "not": "cart_return_bay"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "move_away_from_return_bay_with_cart"
    }
  },
  {
    "id": "no_interactions_after_cart_return",
    "text": "After the cart has been returned to the bay, the shopper should not perform any further store interactions before exiting.",
    "abstraction": {
      "state_properties": {
        "cart_already_returned": "cartAt(0,1)"
      },
      "events": {
        "post_return_store_interaction": {
          "pre": {
            "and": [
              "cart_already_returned",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_store_interaction"
    }
  },
  {
    "id": "eggs_require_cart_return",
    "text": "Because eggs are fragile, after collecting them from the egg shelf the shopper is obliged to return the cart to the cart return bay.",
    "abstraction": {
      "state_properties": {
        "egg_access_cell": {
          "or": [
            "at(6,4)",
            "at(6,2)"
          ]
        },
        "cart_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "collect_eggs": {
          "pre": {
            "and": [
              "egg_access_cell",
              "PICKUP_ITEM",
              "hasCart"
            ]
          },
          "post": "hasCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "cart_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "collect_eggs",
      "discharge": "return_cart_to_bay"
    }
  }
]
